function testStatsOf(p=player()){if(p.testStats)return p.testStats;const stats=emptyTestStats();for(const s of p.sessions)if(s.mode==='test10'&&s.rankingVersion>=3&&s.review===false)addTestSession(stats,s);return stats;}
function testPercent(count){return count?.total?Math.round(count.correct/count.total*100)+'%':'—'}
