function validateTestStats(raw){const count=r=>r&&Number.isSafeInteger(r.correct)&&Number.isSafeInteger(r.total)&&r.correct>=0&&r.total>=r.correct&&r.total<=1e12;const plain=x=>x&&typeof x==='object'&&!Array.isArray(x);if(!plain(raw)||raw.version!==1||!count(raw)||!Number.isSafeInteger(raw.legacySessions)||raw.legacySessions<0||!count(raw.unattributed)||raw.unattributed.total>raw.total)throw Error('テスト集計が不正です');for(const name of ['byCategory','byQuestion','groups']){if(!plain(raw[name])||Object.keys(raw[name]).length>10000)throw Error('テスト集計の分類が不正です');for(const [key,v]of Object.entries(raw[name])){if(['__proto__','constructor','prototype'].includes(key)||!count(v)||v.total>raw.total)throw Error('テスト集計の値が不正です');if(name==='byQuestion'&&!/^(?:p\d{1,2}|t\d+|s2-\d+)(?:-c)?$/.test(key))throw Error('テスト問題IDが不正です');if(name==='byCategory'&&![...new Set(data.map(q=>q.category)),'県庁所在地'].includes(key))throw Error('テストカテゴリが不正です');if(name==='groups'){const s=v.condition;if(!s||s.mode!=='test10'||s.review!==false||!count(s)||!['name','tap','shape','capital','clue'].includes(s.format)||!['pref','terrain','mix'].includes(s.content)||!['input','region','cats'].every(k=>typeof s[k]==='string')||key!==rankingKey(s))throw Error('テスト集計の条件が不正です')}}}const sum=(name,k)=>Object.values(raw[name]).reduce((a,b)=>a+b[k],0);for(const k of ['correct','total'])if(sum('groups',k)!==raw[k]||sum('byQuestion',k)+raw.unattributed[k]!==raw[k]||sum('byCategory',k)>raw[k])throw Error('テスト集計の合計が一致しません');return JSON.parse(JSON.stringify(raw));}
function pstats(){const r=Object.values(player().records);return {total:r.reduce((a,b)=>a+b.attempts,0),ok:r.reduce((a,b)=>a+b.correct,0),master:r.filter(x=>(x.days||[]).length>=2).length}}
