function mapMarkup(kind,q){let paths=features.map(f=>{const id='p'+f.properties.id;const active=q?.pid===f.properties.id&&!['tap','clue'].includes(game?.options.format);const mastered=(player().records[id]?.days?.length||0)>=2;return `<path class="pref ${active?'active':''} ${kind==='atlas'&&mastered?'mastered':''}" data-id="${id}" d="${f._path}"/>`}).join('');if(kind==='shape'){paths=paths.split('<path').filter(x=>x.includes(`data-id="${q.id}"`)).map(x=>'<path'+x).join('')}let geo='';if(kind==='quiz'&&q&&!q.pid&&game.options.format!=='clue'){geo=game.options.format==='tap'?shuffle(data.filter(x=>!x.pid&&x.category===q.category)).map(t=>geoMarkup(t)).join(''):geoMarkup(q)}if(kind==='atlas'&&atlasItem&&!atlasItem.pid)geo=geoMarkup(atlasItem);const hidden=kind==='quiz'&&game?.options.format==='clue';return `<svg ${kind==='hero'?'aria-hidden="true"':'aria-label="日本地図" role="img"'} viewBox="0 0 780 760" ${hidden?'style="opacity:.25"':''}><g id="mapLayer">${paths}${geo}</g><text x="550" y="45" fill="#789489" font-size="14">N ↑</text></svg>`}
