function constrainMap(v){if(v.length!==4||!v.every(Number.isFinite)||v[2]<=0||v[3]<=0)return [...mapView];const ratio=v[2]/v[3],w=Math.max(6,Math.min(2600,v[2])),h=w/ratio,cx=Math.max(-60,Math.min(840,v[0]+v[2]/2)),cy=Math.max(-60,Math.min(820,v[1]+v[3]/2));return [cx-w/2,cy-h/2,w,h];}
